import contextlib
import io
import json
import unittest

from textkit.cli import COMMANDS, main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class JsonTest(unittest.TestCase):
    def test_shout(self):
        code, out, _ = run("--json", "shout", "hi")
        self.assertEqual(code, 0)
        self.assertEqual(json.loads(out), {"command": "shout", "exit": 0, "output": ["HI"]})

    def test_every_command(self):
        for name, c in COMMANDS.items():
            code, out, _ = run("--json", name, *["x"] * len([a for a, _ in c["args"] if not a.startswith("-")]))
            d = json.loads(out)
            self.assertEqual((d["command"], d["exit"]), (name, code))

    def test_error(self):
        orig = COMMANDS["shout"]["run"]

        def boom(a):
            raise ValueError("bad")
        COMMANDS["shout"]["run"] = boom
        try:
            code, out, err = run("--json", "shout", "x")
        finally:
            COMMANDS["shout"]["run"] = orig
        self.assertEqual(code, 2)
        self.assertEqual(err, "error: bad\n")
        self.assertEqual(json.loads(out), {"command": "shout", "exit": 2, "output": []})

    def test_plain_unchanged(self):
        self.assertEqual(run("shout", "hi"), (0, "HI\n", ""))
import os
import re
import unittest

from textkit.cli import COMMANDS

README = os.path.join(os.path.dirname(__file__), "..", "README.md")


def readme_cells():
    cells = {}
    with open(README, encoding="utf-8") as f:
        for line in f:
            m = re.match(r"^\| `([^`]+)` \| (.*) \|\s*$", line)
            if m:
                cells[m.group(1)] = m.group(2)
    return cells


class DocSyncTest(unittest.TestCase):
    def test_readme_matches_help(self):
        cells = readme_cells()
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, cells, "missing README row")
                self.assertEqual(cells[name], c["help"])

    def test_no_unregistered_rows(self):
        self.assertEqual(set(readme_cells()) - set(COMMANDS), set())


if __name__ == "__main__":
    unittest.main()

